import pandas as pd
from itertools import combinations

# Constants
MIN_PERCENTAGE = 0.75

def task_func(data, cols, percentage):
    try:
        threshold = MIN_PERCENTAGE if percentage is None else float(percentage)
    except (TypeError, ValueError):
        threshold = MIN_PERCENTAGE

    if pd.isna(threshold) or threshold < 0 or threshold > 1:
        threshold = MIN_PERCENTAGE

    if cols is None:
        return []

    seen = set()
    valid_cols = []
    for col in cols:
        if col in seen:
            continue
        seen.add(col)
        if col in data.columns and pd.api.types.is_numeric_dtype(data[col]):
            valid_cols.append(col)

    corr_combinations = []

    if len(valid_cols) < 2:
        return corr_combinations

    for c1, c2 in combinations(valid_cols, 2):
        corr = data[c1].corr(data[c2])
        if pd.notna(corr) and abs(corr) > threshold:
            corr_combinations.append((c1, c2))

    return corr_combinations
